-- Widget types and the properties they bind. Generated by `rebench new`.

format_version = "2.0"

front = jbox.panel {
  graphics = { node = "Panel_Front" },
  widgets = {
    jbox.device_name { graphics = { node = "DeviceName" } },
    jbox.sequence_fader {
      graphics = { node = "fader_onoffbypass" },
      handle_size = 0,
      value = "/custom_properties/builtin_onoffbypass",
    },
    jbox.analog_knob {
      graphics = { node = "knob_level" },
      value = "/custom_properties/level",
    },
  },
}

folded_front = jbox.panel {
  graphics = { node = "Panel_Folded_Front" },
  widgets = {
    jbox.device_name { graphics = { node = "DeviceName_Folded" } },
    jbox.sequence_fader {
      graphics = { node = "fader_onoffbypass_folded" },
      handle_size = 0,
      value = "/custom_properties/builtin_onoffbypass",
    },
  },
}

back = jbox.panel {
  graphics = { node = "Panel_Back" },
  widgets = {
    jbox.device_name { graphics = { node = "DeviceName_Back" } },
    jbox.audio_input_socket  { graphics = { node = "socket_in_left" },   socket = "/audio_inputs/inLeft" },
    jbox.audio_input_socket  { graphics = { node = "socket_in_right" },  socket = "/audio_inputs/inRight" },
    jbox.audio_output_socket { graphics = { node = "socket_out_left" },  socket = "/audio_outputs/outLeft" },
    jbox.audio_output_socket { graphics = { node = "socket_out_right" }, socket = "/audio_outputs/outRight" },
    jbox.placeholder { graphics = { node = "Placeholder" } },
  },
}

folded_back = jbox.panel {
  graphics = { node = "Panel_Folded_Back" },
  cable_origin = { node = "CableOrigin" },
  widgets = {
    jbox.device_name { graphics = { node = "DeviceName_Back_Folded" } },
  },
}
